using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed "Discriminator" to "$type". Keep the old property name
            // so existing 500K documents remain readable without migration.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id format from "EntityName|<key>" to just "<key>".
            // Use IdProperty override to preserve the "Product|<key>" format used by
            // existing documents.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id");

            entity.HasIndex(p => p.Sku);
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF Core 9 removes sync I/O support for Cosmos by default.
        // Existing sync calls (e.g. .ToList()) must be converted to async.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

